#!/usr/bin/env bash

set -euo pipefail

# Run GIAB small-variant benchmarking with hap.py and the RTG vcfeval engine.
#
# The script reads the prepared GIAB input manifest generated by:
#   scripts/run_prepare_giab_inputs.sh
#
# Required inputs:
#   --input-manifest
#       TSV containing sample-specific truth VCF, query VCF,
#       benchmark BED, truth version, and biological sex.
#
#   --reference-fasta
#       GRCh38 no-alt reference FASTA used for alignment and variant calling.
#
#   --rtg-sdf
#       RTG reference SDF generated from the same reference assembly.
#
#   --output-root
#       Root directory for sample-specific hap.py results.
#
# Benchmarking is restricted to:
#   custom panel BED ∩ GIAB confident small-variant regions.

usage() {
    cat <<'EOF'
Usage:
  run_giab_benchmark.sh \
    --input-manifest FILE \
    --reference-fasta FILE \
    --rtg-sdf DIRECTORY \
    --output-root DIRECTORY
EOF
}


INPUT_MANIFEST=""
REFERENCE_FASTA=""
RTG_SDF=""
OUTPUT_ROOT=""


while [[ $# -gt 0 ]]; do
    case "$1" in
        --input-manifest)
            [[ $# -ge 2 ]] || {
                echo "ERROR: --input-manifest requires a path." >&2
                exit 2
            }

            INPUT_MANIFEST="$2"
            shift 2
            ;;

        --reference-fasta)
            [[ $# -ge 2 ]] || {
                echo "ERROR: --reference-fasta requires a path." >&2
                exit 2
            }

            REFERENCE_FASTA="$2"
            shift 2
            ;;

        --rtg-sdf)
            [[ $# -ge 2 ]] || {
                echo "ERROR: --rtg-sdf requires a path." >&2
                exit 2
            }

            RTG_SDF="$2"
            shift 2
            ;;

        --output-root)
            [[ $# -ge 2 ]] || {
                echo "ERROR: --output-root requires a path." >&2
                exit 2
            }

            OUTPUT_ROOT="$2"
            shift 2
            ;;

        -h|--help)
            usage
            exit 0
            ;;

        *)
            echo "ERROR: Unknown argument: $1" >&2
            usage >&2
            exit 2
            ;;
    esac
done


if [[ -z "$INPUT_MANIFEST" ]]; then
    echo "ERROR: --input-manifest is required." >&2
    exit 2
fi

if [[ -z "$REFERENCE_FASTA" ]]; then
    echo "ERROR: --reference-fasta is required." >&2
    exit 2
fi

if [[ -z "$RTG_SDF" ]]; then
    echo "ERROR: --rtg-sdf is required." >&2
    exit 2
fi

if [[ -z "$OUTPUT_ROOT" ]]; then
    echo "ERROR: --output-root is required." >&2
    exit 2
fi


for required_file in \
    "$INPUT_MANIFEST" \
    "$REFERENCE_FASTA"
do
    if [[ ! -s "$required_file" ]]; then
        echo \
            "ERROR: Required file is missing or empty: $required_file" \
            >&2
        exit 1
    fi
done


if [[ ! -d "$RTG_SDF" ]]; then
    echo "ERROR: RTG SDF directory is missing: $RTG_SDF" >&2
    exit 1
fi


for tool in \
    hap.py \
    bcftools \
    rtg
do
    if ! command -v "$tool" >/dev/null 2>&1; then
        echo "ERROR: Required tool is unavailable: $tool" >&2
        exit 1
    fi
done


export HGREF="$REFERENCE_FASTA"

mkdir -p "$OUTPUT_ROOT"

RUN_TABLE="$OUTPUT_ROOT/giab_benchmark_runs.tsv"

printf \
    'sample_id\ttruth_version\tsex\toutput_prefix\tsummary_csv\textended_csv\tcomparison_vcf\tstatus\n' \
    > "$RUN_TABLE"


CONTROL_COUNT=0


while IFS=$'\t' read -r \
    sample_id \
    truth_version \
    sex \
    benchmark_bed \
    truth_panel_vcf \
    query_panel_vcf \
    benchmarkable_bases \
    truth_variant_records \
    query_variant_records
do
    if [[ "$sample_id" == "sample_id" ]]; then
        continue
    fi

    CONTROL_COUNT=$((CONTROL_COUNT + 1))

    echo
    echo "[INFO] Running GIAB benchmark: $sample_id"
    echo "[INFO] Truth version: $truth_version"
    echo "[INFO] Biological sex: $sex"
    echo "[INFO] Benchmarkable bases: $benchmarkable_bases"

    for required_file in \
        "$benchmark_bed" \
        "$truth_panel_vcf" \
        "${truth_panel_vcf}.tbi" \
        "$query_panel_vcf" \
        "${query_panel_vcf}.tbi"
    do
        if [[ ! -s "$required_file" ]]; then
            echo \
                "ERROR: Required benchmark input is missing: $required_file" \
                >&2
            exit 1
        fi
    done

    SAMPLE_DIR="$OUTPUT_ROOT/$sample_id"
    OUTPUT_PREFIX="$SAMPLE_DIR/${sample_id}.happy"

    SUMMARY_CSV="${OUTPUT_PREFIX}.summary.csv"
    EXTENDED_CSV="${OUTPUT_PREFIX}.extended.csv"
    COMPARISON_VCF="${OUTPUT_PREFIX}.vcf.gz"
    WARNING_LOG="$SAMPLE_DIR/${sample_id}.happy.warnings.log"

    mkdir -p "$SAMPLE_DIR"

    rm -f \
        "${OUTPUT_PREFIX}".* \
        "$WARNING_LOG"

    hap.py \
        --engine=vcfeval \
        --engine-vcfeval-template "$RTG_SDF" \
        --gender "$sex" \
        -r "$REFERENCE_FASTA" \
        -f "$benchmark_bed" \
        -o "$OUTPUT_PREFIX" \
        "$truth_panel_vcf" \
        "$query_panel_vcf" \
        2> "$WARNING_LOG"

    if [[ ! -s "$SUMMARY_CSV" ]]; then
        echo \
            "ERROR: hap.py summary was not produced for $sample_id." \
            >&2
        exit 1
    fi

    bcftools view \
        -h \
        "$COMPARISON_VCF" \
        >/dev/null

    printf \
        '%s\t%s\t%s\t%s\t%s\t%s\t%s\tcompleted\n' \
        "$sample_id" \
        "$truth_version" \
        "$sex" \
        "$OUTPUT_PREFIX" \
        "$SUMMARY_CSV" \
        "$EXTENDED_CSV" \
        "$COMPARISON_VCF" \
        >> "$RUN_TABLE"

    echo "[INFO] GIAB benchmark completed: $sample_id"
done < "$INPUT_MANIFEST"


if (( CONTROL_COUNT == 0 )); then
    echo "ERROR: The GIAB input manifest contains no controls." >&2
    exit 1
fi


echo
echo "[INFO] Completed GIAB benchmarks: $CONTROL_COUNT"
echo "[INFO] Benchmark run table: $RUN_TABLE"
